ZK proof: Circom 2.1.8 · Groth16 · 844 constraints · 564ms prove · 25ms verify.
Teudat Zehut: 9 digits with Luhn mod-10 check. Leading zeros if necessary.
// packages/verify-local/src/document/countries/IL.ts
import { CountryVerifier, DocumentResult, NumberValidation } from "../verifier.interface";

const IL: CountryVerifier = {
  countryCode:   "IL",
  countryName:   "Israel",
  documentTypes: ["teudat_zehut"],

  parse(ocrText: string): DocumentResult {
    // Teudat Zehut (ID) format: 9 digits with Luhn
    const doc_number = ocrText.match(/(\d{9})/)?.[1] ?? "";
    return { valid: !!doc_number, doc_number, country: "IL" };
  },

  validate(docNumber: string): NumberValidation {
    // Luhn mod-10 check
    return { valid: luhnCheck(docNumber.padStart(9,'0')) };
  },
};

export default IL;

